export const getCurrencySymbol = (code) => {
  const symbolMap = {
    usd: '$',
    eur: '€',
    gbp: '£',
    cad: 'C$',
    aud: 'A$',
    huf: 'Ft'
  };
  
  return symbolMap[code] || '$';
};

